\title{M\"obius Weights, Local Orders, and a Counting Criterion for Freeness}
\author{Aristotle}
\date{11 August 2026}

\begin{document}
\maketitle

\begin{abstract}
Let $\Lambda$ be an order and $M$ a $\Lambda$-lattice. Solomon's zeta function
$\zeta_M(s)=\sum_N [M:N]^{-s}$, summed over finite-index $\Lambda$-submodules, is controlled by
the quotient-type counting function $a_M(X)=\#\{N\le M: M/N\cong X\}$ and hence by the
\emph{M\"obius weight}
\[
  w(M,X)=\sum_{Y\le X}\mu(Y,X)\,\#\Hom_\Lambda(M,Y)=\#\Surj_\Lambda(M,X)=\#\Aut_\Lambda(X)\,a_M(X),
\]
where $\mu$ is the M\"obius function of the lattice of $\Lambda$-submodules of $X$. We prove:
(i) a \emph{locality ascent} criterion --- a commutative module-finite algebra $\Lambda$ over a
local ring $R$ possessing a maximal ideal $J$ all of whose elements have a power in
$\mm_R\Lambda$ is local with $\mm_\Lambda = J$; (ii) that $\Zp[G]$ is local with residue field
$\Fp$ for every finite abelian group $G$ of $p$-power exponent, so that the closed formula
$\#\Aut(X)\,a_{\Lambda^n}(X)=\big(\prod_{i<d}(p^n-p^i)\big)|\mm X|^{n}$,
$d=\dim_{\Fp}X/\mm X$, holds verbatim over this non-maximal, non-domain order; (iii) that over
a noetherian local ring with finite residue field of size $q$ a finitely generated module $M$ is
free of rank $n$ \emph{if and only if} $w(M,X)=\big(\prod_{i<d}(q^n-q^i)\big)|\mm X|^{n}$ for
every finite quotient type $X$, via a counting rigidity plus Krull's intersection theorem, and
that this family of test spaces cannot be reduced to the single residual space $k^{\,n+1}$;
and (iv) that Hom-counts are multiplicative along direct sums, so the weight depends on $M$
only through the function $Y\mapsto\#\Hom(M,Y)$. Along the way we recover Hall's formula, the
Gaussian binomial evaluation and the Jordan-totient identity for cyclic quotients as instances
of a single Nakayama collapse.
\end{abstract}

\section{Introduction}

\subsection{Counting sublattices}

The finite-index subgroups of $\mathbb{Z}^n$ are counted by
\[
  \zeta_{\mathbb{Z}^n}(s)=\sum_{[\mathbb{Z}^n:N]<\infty}[\mathbb{Z}^n:N]^{-s}
   =\zeta(s)\zeta(s-1)\cdots\zeta(s-n+1),
\]
which prime by prime says that the number of sublattices of $\Zp^n$ of index $p^k$ is the
coefficient of $T^k$ in $\prod_{i=0}^{n-1}(1-p^iT)^{-1}$.

Replacing $\mathbb{Z}$ by an \emph{order} $\Lambda$ (a ring that is finitely generated as a
$\mathbb{Z}$- or $\Zp$-module) and $\mathbb{Z}^n$ by a $\Lambda$-lattice $M$, the series
\[
  \zeta_M(s)=\sum_{\substack{N\le M\ \Lambda\text{-submodule}\\ [M:N]<\infty}}[M:N]^{-s}
\]
is \emph{Solomon's zeta function}. Its local factors are rational in $p^{-s}$, but explicit
formulas are rare. This paper studies these coefficients through the M\"obius function of the
submodule lattice of the quotient type, obtains complete answers for free lattices over local
orders, and proves a converse: those coefficients characterise freeness.

\subsection{Notation}

For a commutative ring $R$ and $R$-modules $M,X$ we write $\Hom(M,X)$ and $\Surj(M,X)$ for the
sets of $R$-linear and of surjective $R$-linear maps. A \emph{finite quotient type} is a finite,
finitely generated $R$-module. For $R$ local with maximal ideal $\mm$ and residue field
$k=R/\mm$, the \emph{residual dimension} of $X$ is $d(X)=\dim_k X/\mm X$; by Nakayama it is the
minimal number of generators of $X$. Finally $\mu(Y,Z)$ denotes the M\"obius function of the
poset of $R$-submodules of $X$, defined by $\mu(Y,Y)=1$ and $\mu(Y,Z)=-\sum_{Y\le W<Z}\mu(Y,W)$.

\section{The M\"obius weight}

\begin{definition}\label{def:weight}
Let $R$ be a commutative ring, $M$ an $R$-module and $X$ a finite $R$-module. The
\emph{M\"obius weight of $M$ at $X$} is
\[
  w(M,X):=\sum_{Y\le X}\mu(Y,X)\,\#\Hom_R(M,Y)\ \in\ \mathbb{Z}.
\]
\end{definition}

\begin{proposition}[Surjection count]\label{prop:surj}
$w(M,X)=\#\Surj_R(M,X)$ for every $M$ and every finite $X$.
\end{proposition}

\begin{proof}
Sorting homomorphisms by their image gives $\#\Hom(M,Y)=\sum_{Z\le Y}\#\Surj(M,Z)$ for all
$Y\le X$; M\"obius inversion on the finite submodule lattice of $X$ inverts this triangular
relation.
\end{proof}

\begin{proposition}[Orbit identity]\label{prop:orbit}
For every finite quotient type $X$,
$\#\Aut_R(X)\cdot\#\{N\le M: M/N\cong X\}=\#\Surj_R(M,X)=w(M,X)$.
\end{proposition}

\begin{proof}
$\Aut(X)$ acts freely on $\Surj(M,X)$ by post-composition and two surjections share an orbit
exactly when they share a kernel; orbits correspond to submodules $N$ with $M/N\cong X$.
\end{proof}

Consequently $\zeta_M(s)=\sum_{[X]}\frac{w(M,X)}{\#\Aut(X)}|X|^{-s}$. Three structural
consequences are recorded for later use: $w(M,X)\ge 0$; $\#\Aut(X)$ divides $w(M,X)$; and
$w(M,X)=0$ exactly when $M$ admits no surjection onto $X$. In particular the least $n$ with
$w(R^n,X)\ne0$ is the minimal number of generators of $X$.

\begin{theorem}[Multiplicativity along direct sums]\label{thm:dirsum}
For $R$-modules $M_1,\dots,M_m$ and any $R$-module $Y$,
\[
  \#\Hom_R\Big(\bigoplus_{i=1}^m M_i,\;Y\Big)=\prod_{i=1}^m \#\Hom_R(M_i,Y).
\]
\end{theorem}

\begin{proof}
The universal property of the coproduct yields a natural isomorphism
$\Hom(\bigoplus_i M_i,Y)\cong\prod_i\Hom(M_i,Y)$.
\end{proof}

\begin{corollary}\label{cor:weightsum}
For a finite $R$-module $X$,
$w\big(\bigoplus_{i} M_i, X\big)=\sum_{Y\le X}\mu(Y,X)\prod_i \#\Hom_R(M_i,Y)$.
\end{corollary}

\begin{theorem}[The weight sees only the Hom-count function]\label{thm:homcount}
If $\#\Hom_R(M,Y)=\#\Hom_R(M',Y)$ for every submodule $Y\le X$, then $w(M,X)=w(M',X)$.
\end{theorem}

\begin{proof}
The two defining sums agree term by term.
\end{proof}

Theorem~\ref{thm:homcount} is the structural reason the Solomon coefficients of a decomposable
lattice reduce to data of its indecomposable summands: over $\Lambda=\Zp[\mathbb{Z}/p\mathbb{Z}]$,
where every lattice is a direct sum of copies of the three indecomposables $\Zp$,
$\Zp[\zeta_p]$ and $\Lambda$, Corollary~\ref{cor:weightsum} expresses the weight of an arbitrary
lattice as a M\"obius sum of a product of three Hom-count functions.

\section{Nakayama collapse and Hall's formula}

\begin{lemma}[Nilpotent-ideal Nakayama]\label{lem:nak}
Let $I\subseteq R$ be an ideal, $X$ an $R$-module with $I^eX=0$, and $Y\le X$ with $Y+IX=X$.
Then $Y=X$.
\end{lemma}

\begin{proof}
$X=Y+IX=Y+I(Y+IX)=Y+I^2X=\cdots=Y+I^eX=Y$.
\end{proof}

\begin{theorem}[Hall's formula over $\mathbb{Z}$]\label{thm:hall}
Let $p$ be prime and $X$ a finite abelian $p$-group with $d=\dim_{\Fp}X/pX$. Then for all $n$,
\[
  \#\Aut(X)\cdot\#\{N\le\mathbb{Z}^n:\mathbb{Z}^n/N\cong X\}
   =\Big(\prod_{i=0}^{d-1}(p^n-p^i)\Big)\cdot|pX|^{\,n}.
\]
\end{theorem}

\begin{proof}[Proof sketch]
By Proposition~\ref{prop:orbit} the left side counts generating $n$-tuples of $X$. By
Lemma~\ref{lem:nak} with $I=(p)$, a tuple generates $X$ iff its image spans the $\Fp$-space
$X/pX$. The reduction $X^n\to(X/pX)^n$ is onto with all fibres of size $|pX|^n$, and the
spanning $n$-tuples of a $d$-dimensional $\Fp$-space number $\prod_{i<d}(p^n-p^i)$.
\end{proof}

\begin{remark}
The right-hand side depends on $X$ only through the pair $(|pX|,d)$. For $X$ of partition type
$\lambda$ one has $d=\#\mathrm{parts}(\lambda)$ and $|pX|=p^{|\lambda|-d}$, so
$w(\mathbb{Z}^n,X)=p^{\,n(|\lambda|-d)}\prod_{i<d}(p^n-p^i)$.
\end{remark}

\begin{corollary}[Gaussian binomial]\label{cor:gauss}
For $X=(\mathbb{Z}/p)^d$ we have $pX=0$ and $\#\Aut(X)=\#\GL_d(\Fp)=\prod_{i<d}(p^d-p^i)$, so
\[
  \#\{N\le\mathbb{Z}^n:\mathbb{Z}^n/N\cong(\mathbb{Z}/p)^d\}
  =\frac{\prod_{i<d}(p^n-p^i)}{\prod_{i<d}(p^d-p^i)}=\binom{n}{d}_p ,
\]
the number of $d$-codimensional subspaces of $\Fp^{\,n}$.
\end{corollary}

The linear-algebra input is a rank duality: the columns of a $d\times n$ matrix over a field
span $\Fp^d$ if and only if its rows are linearly independent in $\Fp^n$.

\begin{corollary}[Cyclic quotients and Jordan's totient]\label{cor:jordan}
For every $m\ge1$,
\[
  \varphi(m)\cdot\#\{N\le\mathbb{Z}^n:\mathbb{Z}^n/N\cong\mathbb{Z}/m\}
  =\sum_{d\mid m}\mu_{\mathrm{arith}}(d)\Big(\frac{m}{d}\Big)^n=J_n(m).
\]
\end{corollary}

\begin{proof}[Proof sketch]
For coprime cardinalities the submodule lattice of $X_1\oplus X_2$ is a product of posets, whose
M\"obius function is the product; hence $w(\mathbb{Z}^n,-)$ is multiplicative and the claim
reduces to prime powers, where Theorem~\ref{thm:hall} with $d=1$ gives
$w(\mathbb{Z}^n,\mathbb{Z}/p^e)=(p^e)^n-(p^{e-1})^n$.
\end{proof}

Corollary~\ref{cor:jordan} is the precise sense in which the incidence-algebra M\"obius function
of the submodule poset is carried onto the arithmetic M\"obius function.

\section{Local orders: the general formula}

Let $R$ be commutative local with maximal ideal $\mm$ and finite residue field $k$, $q=|k|$.

\begin{theorem}[Local Nakayama collapse]\label{thm:local}
For every finite $R$-module $X$ with $d=\dim_k X/\mm X$ and every $n$,
\[
  w(R^n,X)=\Big(\prod_{i=0}^{d-1}(q^n-q^i)\Big)\cdot|\mm X|^{\,n},
\]
equivalently
$\#\Aut_R(X)\cdot\#\{N\le R^n:R^n/N\cong X\}=\big(\prod_{i<d}(q^n-q^i)\big)|\mm X|^{n}$.
\end{theorem}

\begin{proof}[Proof sketch]
As in Theorem~\ref{thm:hall}: $w(R^n,X)=\#\Surj(R^n,X)$ is the number of generating $n$-tuples;
Nakayama says a tuple generates iff its residue spans $X/\mm X$; the fibres of
$X^n\to(X/\mm X)^n$ have size $|\mm X|^n$ and the spanning tuples in $k^d$ number
$\prod_{i<d}(q^n-q^i)$.
\end{proof}

\begin{corollary}\label{cor:twoinv}
Over a local order the Solomon coefficient of $R^n$ at $X$ depends on $X$ only through the pair
$(|\mm X|,\dim_k X/\mm X)$.
\end{corollary}

Summing over quotient types of a given length recovers the classical shape: over $\Zp$ with
$p=2$ the coefficient sequences of $\sum_X a_{\Zp^n}(X)T^{\log_p|X|}$ are $1,1,1,1,\dots$ for
$n=1$; $1,3,7,15,31,\dots$ for $n=2$; $1,7,35,155,651,\dots$ for $n=3$, i.e.\ the expansions of
$\prod_{i<n}(1-2^iT)^{-1}$.

\section{Locality ascent and $p$-adic group rings}

\begin{lemma}[Nakayama unit criterion]\label{lem:unit}
Let $R$ be commutative local with maximal ideal $\mm$ and $\Lambda$ a commutative $R$-algebra
that is finitely generated as an $R$-module. If $x\Lambda+\mm\Lambda=\Lambda$, then $x$ is a
unit of $\Lambda$.
\end{lemma}

\begin{proof}
The finitely generated $R$-module $\Lambda/x\Lambda$ satisfies
$\mm\cdot(\Lambda/x\Lambda)=\Lambda/x\Lambda$, so Nakayama gives $\Lambda/x\Lambda=0$.
\end{proof}

\begin{lemma}[Geometric series]\label{lem:geom}
With $R,\Lambda$ as above, if $a^N\in\mm\Lambda$ for some $N$, then $1-a$ is a unit.
\end{lemma}

\begin{proof}
$(1-a)\sum_{i<N}a^i=1-a^N$ places $1$ in $(1-a)\Lambda+\mm\Lambda$; apply
Lemma~\ref{lem:unit}.
\end{proof}

\begin{theorem}[Locality ascent]\label{thm:ascent}
Let $R$ be commutative local and $\Lambda$ a commutative $R$-algebra that is finitely generated
as an $R$-module. If $\Lambda$ has a maximal ideal $J$ such that every $a\in J$ has some power
in $\mm_R\Lambda$ --- i.e.\ $J/\mm_R\Lambda$ is nil in $\Lambda/\mm_R\Lambda$ --- then $\Lambda$
is local with $\mm_\Lambda=J$.
\end{theorem}

\begin{proof}
It suffices that for each $a\in\Lambda$ either $a$ or $1-a$ is a unit. If $a\in J$, then $1-a$
is a unit by Lemma~\ref{lem:geom}. If $a\notin J$, maximality gives $y\in\Lambda$, $i\in J$ with
$ya=1-i$, a unit by Lemma~\ref{lem:geom}; hence $a$ is a unit. A maximal ideal of a local ring
is the maximal ideal.
\end{proof}

The hypothesis is nilpotence \emph{modulo the base}: over $R=\Zp$ the element $p$ is not
nilpotent but lies in $\mm_R\Lambda$, which is all the argument needs.

\begin{lemma}\label{lem:augnil}
In $\Fp[G]$ with $G$ of exponent dividing $p^e$, every element $u$ of the augmentation ideal
satisfies $u^{p^e}=0$.
\end{lemma}

\begin{proof}[Proof sketch]
In characteristic $p$ the $p^e$-power map is a ring homomorphism, so for $u=\sum_g c_g g$,
$u^{p^e}=\sum_g c_g^{p^e}g^{p^e}=\big(\sum_g c_g\big)\cdot 1=\varepsilon(u)=0$.
\end{proof}

\begin{lemma}\label{lem:red}
Coefficientwise reduction induces a surjection $\rho:\Zp[G]\to\Fp[G]$ commuting with the
augmentations, and $\ker\rho\subseteq p\,\Zp[G]=\mm_{\Zp}\Lambda$.
\end{lemma}

\begin{theorem}[$p$-adic group rings of abelian $p$-groups are local]\label{thm:grouplocal}
Let $G$ be a finite abelian group of exponent dividing $p^e$. Then $\Lambda=\Zp[G]$ is local
with $\mm_\Lambda=\varepsilon^{-1}(p\Zp)$, the sum of the augmentation ideal and $p\Lambda$, and
$\Lambda/\mm_\Lambda\cong\Fp$.
\end{theorem}

\begin{proof}
$J:=\varepsilon^{-1}(p\Zp)$ is maximal with $\Lambda/J\cong\Fp$ because $\varepsilon$ is onto and
$p\Zp$ is maximal. For $a\in J$, $\rho(a)$ has zero augmentation, so $\rho(a^{p^e})=0$ by
Lemma~\ref{lem:augnil}, whence $a^{p^e}\in\mm_{\Zp}\Lambda$ by Lemma~\ref{lem:red}. As $\Lambda$
is free of rank $|G|$ over $\Zp$, Theorem~\ref{thm:ascent} applies.
\end{proof}

\begin{theorem}[Free Solomon coefficients over $\Zp[G]$]\label{thm:groupcoeff}
With $G,\Lambda$ as above, for every finite $\Lambda$-module $X$ with
$d=\dim_{\Fp}X/\mm X$ and every $n$,
\[
  \#\Aut_\Lambda(X)\cdot\#\{N\le\Lambda^n:\Lambda^n/N\cong X\}
  =\Big(\prod_{i=0}^{d-1}(p^n-p^i)\Big)\cdot|\mm X|^{\,n}.
\]
\end{theorem}

\begin{proof}
Combine Theorem~\ref{thm:grouplocal} ($q=p$) with Theorem~\ref{thm:local}.
\end{proof}

For $G=\mathbb{Z}/p\mathbb{Z}$ the order $\Lambda\cong\Zp[x]/(x^p-1)$ is not maximal and has zero
divisors, since $(x-1)(1+x+\cdots+x^{p-1})=0$; the coefficients are nonetheless those of the
maximal order.

\begin{example}
Take $p=2$ and the finite quotient $\Lambda_2=(\mathbb{Z}/4)[x]/(x^2-1)$, of order $16$, with
$\mm$ the elements of even coefficient sum. For $X=\Lambda_2$ we have $d=1$, $|\mm X|=8$, and
Theorem~\ref{thm:groupcoeff} predicts $(2^n-1)8^n$ surjections $\Lambda^n\twoheadrightarrow X$:
$8$ for $n=1$ and $192$ for $n=2$; exhaustive enumeration confirms both. For
$X=\Lambda_2/(x-1)\cong\mathbb{Z}/4$ one gets $2$ and $12$; for $X=\Fp$, $1$ and $3$.
\end{example}

\section{A M\"obius characterisation of freeness}

Throughout, $R$ is commutative local with maximal ideal $\mm$ and finite residue field $k$,
$q=|k|$, and $M$ is a finitely generated $R$-module.

\begin{definition}
For $n\in\mathbb{N}$ and a finite $R$-module $X$ with $d=\dim_kX/\mm X$ put
$\fw_n(X):=\big(\prod_{i<d}(q^n-q^i)\big)\,|\mm X|^{\,n}$, so Theorem~\ref{thm:local} reads
$w(R^n,X)=\fw_n(X)$.
\end{definition}

\begin{lemma}\label{lem:res}
$\mm\cdot k^m=0$ and $\dim_k(k^m/\mm k^m)=m$; consequently $\fw_n(k^{\,n+1})=0$, because the
product $\prod_{i<n+1}(q^n-q^i)$ contains the vanishing factor $i=n$.
\end{lemma}

\begin{lemma}\label{lem:gen}
If $w(M,k^{\,n+1})=0$ then $\dim_kM/\mm M\le n$, and then there is a surjection
$\pi:R^n\twoheadrightarrow M$.
\end{lemma}

\begin{proof}[Proof sketch]
If $\dim_kM/\mm M>n$, projecting a residual basis onto $n+1$ coordinates produces a surjection
$M\twoheadrightarrow k^{\,n+1}$, so $w(M,k^{n+1})>0$ by Proposition~\ref{prop:surj}. Conversely,
lifting a residual spanning family of size $\le n$ to $M$ gives generators by Nakayama.
\end{proof}

\begin{theorem}[Free modules maximise the weights]\label{thm:max}
If $M$ is generated by at most $n$ elements, then $w(M,X)\le w(R^n,X)=\fw_n(X)$ for every finite
quotient type $X$.
\end{theorem}

\begin{proof}
For a surjection $\pi:R^n\twoheadrightarrow M$ the map $g\mapsto g\circ\pi$ sends $\Surj(M,X)$
into $\Surj(R^n,X)$ and is injective because $\pi$ is onto; both sets are finite since
$\Hom(R^n,X)\cong X^n$ is. Apply Proposition~\ref{prop:surj}.
\end{proof}

\begin{theorem}[Counting rigidity]\label{thm:rigid}
Let $\pi:R^n\twoheadrightarrow M$ be a surjection and $X$ a finite $R$-module with
$\#\Surj(M,X)=\#\Surj(R^n,X)$. Then every surjection $f:R^n\twoheadrightarrow X$ satisfies
$\ker\pi\subseteq\ker f$.
\end{theorem}

\begin{proof}
The injection of Theorem~\ref{thm:max} is a map between finite sets of equal cardinality, hence
bijective; choose $g$ with $g\circ\pi=f$. For $x\in\ker\pi$, $f(x)=g(\pi(x))=0$.
\end{proof}

\begin{lemma}\label{lem:finquot}
If $R$ is noetherian local with finite residue field then $R/\mm^j$ is finite for every $j$, and
hence so is $R^n/\mm^jR^n$.
\end{lemma}

\begin{proof}[Proof sketch]
The graded pieces $\mm^i/\mm^{i+1}$ are finitely generated over the finite field $k$; $R/\mm^j$
has a finite filtration with these quotients. Then $R^n/\mm^jR^n\cong(R/\mm^j)^n$.
\end{proof}

\begin{theorem}[Freeness is detected by the M\"obius weights]\label{thm:free}
Let $R$ be a noetherian commutative local ring with finite residue field $k$, $q=|k|$, and let
$M$ be a finitely generated $R$-module. Then for $n\ge0$,
\[
  M\cong R^n \iff w(M,X)=\fw_n(X)\ \text{for every finite quotient type }X.
\]
\end{theorem}

\begin{proof}
($\Rightarrow$) is Theorem~\ref{thm:local}. For ($\Leftarrow$), apply the hypothesis at
$X=k^{\,n+1}$: by Lemma~\ref{lem:res} the right side vanishes, so by Lemma~\ref{lem:gen} there
is a surjection $\pi:R^n\twoheadrightarrow M$. Fix $j\ge1$ and set $X_j:=R^n/\mm^jR^n$, a finite
quotient type by Lemma~\ref{lem:finquot}. By hypothesis and Theorem~\ref{thm:local},
$\#\Surj(M,X_j)=w(M,X_j)=\fw_n(X_j)=\#\Surj(R^n,X_j)$, so Theorem~\ref{thm:rigid} applies to the
canonical projection $R^n\twoheadrightarrow X_j$ and yields
$\ker\pi\subseteq\mm^jR^n$. As $j$ was arbitrary, Krull's intersection theorem gives
$\ker\pi\subseteq\bigcap_j\mm^jR^n=0$, so $\pi$ is an isomorphism.
\end{proof}

\begin{corollary}[$p$-adic case]
A finitely generated $\Zp$-module $M$ is free of rank $n$ iff for every finite $\Zp$-module $X$,
$\sum_{Y\le X}\mu(Y,X)\#\Hom(M,Y)=\big(\prod_{i<d}(p^n-p^i)\big)|pX|^{n}$ with
$d=\dim_{\Fp}X/pX$.
\end{corollary}

\begin{corollary}[Freeness over $\Zp[G]$]\label{cor:groupfree}
Let $G$ be a finite abelian group of exponent dividing $p^e$ and $\Lambda=\Zp[G]$. A finitely
generated $\Lambda$-module $M$ is free of rank $n$ iff for every finite $\Lambda$-module $X$,
\[
  \sum_{Y\le X}\mu(Y,X)\,\#\Hom_\Lambda(M,Y)
   =\Big(\prod_{i<d}(p^n-p^i)\Big)\cdot|\mm X|^{\,n},\qquad d=\dim_{\Fp}X/\mm X .
\]
\end{corollary}

\begin{proof}
$\Lambda$ is module-finite over $\Zp$, hence noetherian, and local with residue field $\Fp$ by
Theorem~\ref{thm:grouplocal}; apply Theorem~\ref{thm:free}.
\end{proof}

\begin{theorem}[Sharpness: one test space is not enough]\label{thm:sharp}
Let $R=\Zp$, $n=1$ and $M=\Fp$ regarded as a cyclic $\Zp$-module. Then
$w(M,\Fp^{\,2})=0=\fw_1(\Fp^{\,2})$, yet $M$ is not free of rank one.
\end{theorem}

\begin{proof}
$\fw_1(\Fp^2)=0$ by Lemma~\ref{lem:res}. A surjection $M\twoheadrightarrow\Fp^2$ would force
$p^2\le p$, so $w(M,\Fp^2)=0$ as well. Finally $M$ is finite and $\Zp$ is not.
\end{proof}

\begin{remark}
The pair is separated by $X=\mathbb{Z}/p^2$, where $\fw_1(X)=(p-1)p=\varphi(p^2)>0$ while
$w(\Fp,\mathbb{Z}/p^2)=0$. Thus the residual test space detects the number of generators --- a
one-space invariant --- but freeness is not a one-space invariant; the family
$\{R^n/\mm^jR^n\}_{j\ge1}$ is what does the work in Theorem~\ref{thm:free}.
\end{remark}

\section{Algorithms}

\paragraph{M\"obius weight by lattice inversion.} Enumerate all submodules of $X$ by saturating
generating sets; sort them by cardinality and compute $\mu$ recursively; evaluate
$\#\Hom(M,Y)$ for each; sum. With $s$ submodules the M\"obius table costs $O(s^3)$ in the worst
case, which is why the closed formulas matter.

\paragraph{Closed-form free coefficient.} Given $q,n,d,|\mm X|$, return
$\big(\prod_{i<d}(q^n-q^i)\big)|\mm X|^n$ in $O(d)$ big-integer multiplications, and divide by
$\#\Aut(X)$ for the sublattice count.

\paragraph{Freeness test.} Compute $d_M=\dim_kM/\mm M$; if $d_M>n$ report failure (this is the
$X=k^{n+1}$ test). Otherwise choose $\pi:R^n\twoheadrightarrow M$ and compare
$\#\Surj(M,R^n/\mm^jR^n)$ with $\fw_n(R^n/\mm^jR^n)$ for $j=1,2,\dots$: a shortfall certifies
non-freeness, and agreement certifies $\ker\pi\subseteq\mm^jR^n$. An Artin--Rees bound turns
this into a terminating decision procedure.

\section{Discussion and future work}

Over a local order with finite residue field the local factor of the Solomon zeta function of a
\emph{free} lattice is completely explicit, and by Corollary~\ref{cor:twoinv} it is blind to all
of $X$ beyond the pair $(|\mm X|,d)$; the interesting arithmetic therefore lives in the non-free
lattices, where the Nakayama collapse fails and Corollary~\ref{cor:weightsum} is the available
reduction. Theorems~\ref{thm:ascent} and~\ref{thm:grouplocal} are proved for commutative
$\Lambda$; the counting arguments use commutativity only for bookkeeping, so one expects the
same picture for module-finite noncommutative $\Lambda$ whose quotient by the extended maximal
ideal has nil Jacobson radical --- e.g.\ $\Zp[G]$ for a non-abelian $p$-group $G$.

Open directions: (i) the noncommutative ascent just described; (ii) an explicit expression, via
Corollary~\ref{cor:weightsum} and the classification of $\Zp[\mathbb{Z}/p]$-lattices into three
indecomposables, of the weight of an arbitrary lattice as a $\mathbb{Z}$-linear combination of
free-like weights, with a bound on the numerator degree of its zeta function; (iii) rationality
of the refined generating function $\sum_X w(R^n,X)T^{\ell(X)}$ with denominator
$\prod_{i<n}(1-q^iT)$; (iv) the partition form of Hall's formula together with the global Euler
factorization; (v) an explicit Artin--Rees bound making the freeness test terminating.

\section*{Summary of results}

\begin{center}
\begin{tabular}{ll}
\toprule
Result & Statement \\
\midrule
M\"obius weight & $w(M,X)=\sum_{Y\le X}\mu(Y,X)\#\Hom(M,Y)=\#\Surj(M,X)=\#\Aut(X)a_M(X)$\\
Direct sums & $\#\Hom(\bigoplus M_i,Y)=\prod\#\Hom(M_i,Y)$\\
Hall's formula & $\#\Aut(X)a_{\mathbb{Z}^n}(X)=\big(\prod_{i<d}(p^n-p^i)\big)|pX|^n$\\
Gaussian binomial & $a_{\mathbb{Z}^n}((\mathbb{Z}/p)^d)=\binom{n}{d}_p$\\
Cyclic case & $\varphi(m)a_{\mathbb{Z}^n}(\mathbb{Z}/m)=J_n(m)$\\
Local formula & $w(R^n,X)=\big(\prod_{i<d}(q^n-q^i)\big)|\mm X|^n$\\
Locality ascent & $J$ maximal, nil mod $\mm_R\Lambda$ $\Rightarrow$ $\Lambda$ local, $\mm_\Lambda=J$\\
Group rings & $\Zp[G]$ local with residue field $\Fp$ for abelian $p$-groups $G$\\
Maximality & $w(M,X)\le w(R^n,X)$ for $M$ $n$-generated\\
Freeness & $M\cong R^n\iff w(M,X)=\fw_n(X)$ for all $X$\\
Sharpness & over $\Zp$, $\Fp$ matches the rank-one weight at $k^2$ but is not free\\
\bottomrule
\end{tabular}
\end{center}

