"""
Solomon coefficients over the group-ring order Lambda = Z_p[Z/pZ].

Lambda is local with residue field F_p, although it is neither a maximal order
nor a domain: in Z_p[x]/(x^p - 1) one has (x-1)(1 + x + ... + x^{p-1}) = 0.
The theory predicts that for every finite Lambda-module X,

    #Surj(Lambda^n, X) = (prod_{i<d}(p^n - p^i)) * |mX|^n,   d = dim_{F_p} X/mX,

exactly as over the maximal order Z_p.  This script verifies the prediction by
brute-force enumeration inside the finite quotient

    Lambda_e = (Z/p^e)[x]/(x^p - 1),

whose maximal ideal is the set of elements whose coefficient sum is divisible
by p (the preimage of pZ_p under the augmentation).
"""

from __future__ import annotations

from itertools import product
from typing import Dict, FrozenSet, Iterable, List, Tuple

Elt = Tuple[int, ...]  # coefficient vector of length p, entries mod p^e


def ring_elements(p: int, e: int) -> List[Elt]:
    return [tuple(t) for t in product(range(p ** e), repeat=p)]


def radd(p: int, e: int, a: Elt, b: Elt) -> Elt:
    m = p ** e
    return tuple((x + y) % m for x, y in zip(a, b))


def rmul(p: int, e: int, a: Elt, b: Elt) -> Elt:
    """Cyclic convolution = multiplication in (Z/p^e)[x]/(x^p - 1)."""
    m = p ** e
    out = [0] * p
    for i, ai in enumerate(a):
        if ai:
            for j, bj in enumerate(b):
                out[(i + j) % p] = (out[(i + j) % p] + ai * bj) % m
    return tuple(out)


def in_maximal_ideal(p: int, a: Elt) -> bool:
    return sum(a) % p == 0


def ideal_generated(p: int, e: int, gens: Iterable[Elt]) -> FrozenSet[Elt]:
    ring = ring_elements(p, e)
    zero = tuple(0 for _ in range(p))
    seen, frontier, gens = {zero}, [zero], list(gens)
    while frontier:
        cur = frontier.pop()
        for g in gens:
            for r in ring:
                nxt = radd(p, e, cur, rmul(p, e, r, g))
                if nxt not in seen:
                    seen.add(nxt)
                    frontier.append(nxt)
    return frozenset(seen)


def quotient_invariants(p: int, e: int, I: FrozenSet[Elt]) -> Tuple[int, int, int]:
    """For X = Lambda_e / I return (|X|, d, |mX|)."""
    ring = ring_elements(p, e)
    rep: Dict[Elt, Elt] = {a: min(frozenset(radd(p, e, a, i) for i in I)) for a in ring}
    reps = sorted(set(rep.values()))
    mX = {rep[a] for a in ring if in_maximal_ideal(p, a)}
    quot = len(reps) // len(mX)
    d = 0
    while p ** d < quot:
        d += 1
    return len(reps), d, len(mX)


def count_surj(p: int, e: int, I: FrozenSet[Elt], n: int) -> int:
    """#Surj(Lambda^n, Lambda/I) by enumerating n-tuples of cosets."""
    ring = ring_elements(p, e)
    rep: Dict[Elt, Elt] = {a: min(frozenset(radd(p, e, a, i) for i in I)) for a in ring}
    reps = sorted(set(rep.values()))
    return sum(1 for tup in product(reps, repeat=n)
               if len(ideal_generated(p, e, list(tup) + list(I))) == len(ring))


def free_weight(q: int, n: int, d: int, card_mX: int) -> int:
    prod = 1
    for i in range(d):
        prod *= q ** n - q ** i
    return prod * card_mX ** n


def main() -> None:
    p, e = 2, 2
    zero = tuple(0 for _ in range(p))
    x_minus_1 = tuple([(-1) % p ** e, 1] + [0] * (p - 2))
    p_elt = tuple([p] + [0] * (p - 1))
    tests = {
        "X = Lambda": frozenset({zero}),
        "X = Lambda/(x-1)": ideal_generated(p, e, [x_minus_1]),
        "X = Lambda/(p, x-1) = F_p": ideal_generated(p, e, [p_elt, x_minus_1]),
    }
    print(f"Lambda_e = (Z/{p ** e})[x]/(x^{p} - 1),  |Lambda_e| = {p ** (e * p)}")
    print(f"{'quotient type':<28}{'|X|':>5}{'d':>4}{'|mX|':>7}{'n':>4}"
          f"{'#Surj (brute)':>15}{'formula':>10}")
    for label, I in tests.items():
        card, d, card_mX = quotient_invariants(p, e, I)
        for n in (1, 2):
            brute = count_surj(p, e, I, n)
            pred = free_weight(p, n, d, card_mX)
            assert brute == pred, (label, n, brute, pred)
            print(f"{label:<28}{card:>5}{d:>4}{card_mX:>7}{n:>4}{brute:>15}{pred:>10}")
    print("\nAll counts agree with the local formula: the non-maximal, non-domain")
    print("order Z_p[Z/pZ] has the Solomon coefficients of the maximal order.")


if __name__ == "__main__":
    main()

