"""
Visualization 1: the submodule lattice of X = Z/2 x Z/4 with its Moebius
function, and the Moebius inversion that produces the surjection count.

Each node is a subgroup, labelled by its isomorphism type and by mu(Y, X);
edges are covering relations.  The banner underneath shows the inversion
    w(Z^2, X) = sum_Y mu(Y, X) * |Y|^2 = 24 = #Surj(Z^2, X),
so that #{N <= Z^2 : Z^2/N =~ X} = 24 / #Aut(X) = 24 / 8 = 3.

Requires matplotlib.  Saves 'submodule_lattice.png'.
"""

from __future__ import annotations

from itertools import product
from typing import Dict, FrozenSet, List, Tuple

import matplotlib.pyplot as plt

Elt = Tuple[int, int]
MODS = (2, 4)


def elements() -> List[Elt]:
    return [(a, b) for a, b in product(range(MODS[0]), range(MODS[1]))]


def add(a: Elt, b: Elt) -> Elt:
    return ((a[0] + b[0]) % MODS[0], (a[1] + b[1]) % MODS[1])


def gen(gens: List[Elt]) -> FrozenSet[Elt]:
    seen, frontier = {(0, 0)}, [(0, 0)]
    while frontier:
        cur = frontier.pop()
        for g in gens:
            nxt = add(cur, g)
            if nxt not in seen:
                seen.add(nxt)
                frontier.append(nxt)
    return frozenset(seen)


def all_subgroups() -> List[FrozenSet[Elt]]:
    found = {frozenset({(0, 0)})}
    frontier = [frozenset({(0, 0)})]
    while frontier:
        H = frontier.pop()
        for g in elements():
            if g in H:
                continue
            K = gen(list(H) + [g])
            if K not in found:
                found.add(K)
                frontier.append(K)
    return sorted(found, key=lambda H: (len(H), sorted(H)))


def iso_type(H: FrozenSet[Elt]) -> str:
    if len(H) == 1:
        return "0"
    orders = []
    for h in H:
        k, cur = 1, h
        while cur != (0, 0):
            cur = add(cur, h)
            k += 1
        orders.append(k)
    m = max(orders)
    if m == len(H):
        return f"Z/{m}"
    return f"Z/{len(H) // m} x Z/{m}"


def moebius(subs: List[FrozenSet[Elt]]) -> Dict[Tuple[int, int], int]:
    mu: Dict[Tuple[int, int], int] = {}
    order = sorted(range(len(subs)), key=lambda i: len(subs[i]))
    for zi in order:
        for yi in order:
            if not subs[yi] <= subs[zi]:
                continue
            mu[(yi, zi)] = 1 if yi == zi else -sum(
                mu[(yi, wi)] for wi in range(len(subs))
                if subs[yi] <= subs[wi] < subs[zi] and (yi, wi) in mu)
    return mu


def main() -> None:
    subs = all_subgroups()
    mu = moebius(subs)
    top = len(subs) - 1

    # layout: x by "rank" (log2 of order), y spread within a level
    levels: Dict[int, List[int]] = {}
    for i, H in enumerate(subs):
        r = len(H).bit_length() - 1
        levels.setdefault(r, []).append(i)
    pos: Dict[int, Tuple[float, float]] = {}
    for r, idxs in levels.items():
        for j, i in enumerate(idxs):
            pos[i] = (j - (len(idxs) - 1) / 2.0, float(r))

    fig, ax = plt.subplots(figsize=(9, 6.5))
    for i, H in enumerate(subs):
        for j, K in enumerate(subs):
            if H < K and not any(H < subs[m] < K for m in range(len(subs))):
                x1, y1 = pos[i]
                x2, y2 = pos[j]
                ax.plot([x1, x2], [y1, y2], color="#b9c6d8", lw=1.4, zorder=1)
    for i, H in enumerate(subs):
        x, y = pos[i]
        m = mu[(i, top)]
        colour = "#2b6cb0" if m > 0 else ("#c53030" if m < 0 else "#718096")
        ax.scatter([x], [y], s=1500, color=colour, alpha=0.18, zorder=2)
        ax.text(x, y + 0.06, iso_type(H), ha="center", va="center",
                fontsize=10, weight="bold", color="#1a202c", zorder=3)
        ax.text(x, y - 0.10, f"mu = {m},  |Y| = {len(H)}", ha="center", va="center",
                fontsize=8, color=colour, zorder=3)

    total = sum(mu[(i, top)] * len(subs[i]) ** 2 for i in range(len(subs)))
    ax.set_title("Submodule lattice of $X=\\mathbb{Z}/2\\times\\mathbb{Z}/4$ "
                 "with $\\mu(Y,X)$", fontsize=13)
    ax.set_xlabel(f"$\\sum_Y \\mu(Y,X)\\,|Y|^2 = {total} = \\#\\mathrm{{Surj}}"
                  f"(\\mathbb{{Z}}^2, X)$, so $\\#\\{{N: \\mathbb{{Z}}^2/N\\cong X\\}}"
                  f" = {total}/8 = {total // 8}$", fontsize=11)
    ax.set_yticks([])
    ax.set_xticks([])
    for s in ax.spines.values():
        s.set_visible(False)
    ax.margins(0.15)
    fig.tight_layout()
    fig.savefig("submodule_lattice.png", dpi=160)
    print("wrote submodule_lattice.png;  Moebius inversion gives", total)


if __name__ == "__main__":
    main()
